scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_294'] || []

control 'CKV_AWS_294' do
  title 'Ensure CloudTrail Event Data Store uses CMK'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_cloudtrail_event_data_store resources that actually exist,
    enumerated through the two-step (parent -> child) declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    An event data store holds the account's audit history. A
    customer-managed key means access to that history is gated by a key
    policy the account controls, independently of the CloudTrail
    permissions.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_cloudtrail_event_data_store: kms_key_id is
    CKV_ANY
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_cloudtrail_event_data_store:

      resource "aws_cloudtrail_event_data_store" "example" {
        name                           = "audit"
        retention_period               = 2557
        multi_region_enabled           = true
        termination_protection_enabled = true
        kms_key_id                     = aws_kms_key.cloudtrail.arn
      }

    Out of band — aws_cloudtrail_event_data_store:

      aws cloudtrail update-event-data-store --event-data-store <eds-arn> --kms-key-id <key-arn>

    Note (aws_cloudtrail_event_data_store): The KMS key policy must allow
    cloudtrail.amazonaws.com to GenerateDataKey and Decrypt, or the store stops
    ingesting.
  FIX

  tag checkov_id:            'CKV_AWS_294'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_cloudtrail_event_data_store]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/cloudtrail_event_data_store#kms-key-id'
  tag nist:                  ['AU-9', 'SC-28', 'SC-28 (1)']
  tag nist_r4:               ['AU-9', 'SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-000162', 'CCI-001199']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_cloudtrail_event_data_store', regions: scan_regions)

  # A region — or a whole service — that could not be READ is not the same as
