  in_scope.each do |asset|
    describe "aws_cloudtrail_event_data_store #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:kms_key_id] }
      it { should satisfy('be set') { |v| !v.nil? && !(v.respond_to?(:empty?) && v.empty?) } }
